docDates:text:DocumentDates.code:
(function(root){
  const calendar=new Intl.DateTimeFormat('en-US',{
    timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'
  });
  function dateOnly(value){
    if(!value)return '';
    if(typeof value==='string'){
      const day=value.match(/^(\d{4}-\d{2}-\d{2})(?:[T ]00:00:00(?:\.0+)?(?:Z|\+00(?::?00)?))?$/);
      if(day)return day[1];
    }
    const instant=new Date(value);
    if(isNaN(instant.getTime()))return '';
    const parts=Object.fromEntries(calendar.formatToParts(instant).map(p=>[p.type,p.value]));
    return `${parts.year}-${parts.month}-${parts.day}`;
  }
  function addDays(value,days){
    const day=dateOnly(value);
    if(!day)return '';
    // Calendar arithmetic must not gain/lose a day at a daylight-saving change.
    const d=new Date(day+'T00:00:00Z');
    d.setUTCDate(d.getUTCDate()+days);
    return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;
  }
  // Same day of the month, n months on. A day the target month lacks clamps
  // to its last day (Jan 31 + 1 → Feb 28, or Feb 29 in a leap year).
  function addMonths(value,months){
    const day=dateOnly(value);
    if(!day)return '';
    const [y,m,d]=day.split('-').map(Number);
    const idx=y*12+(m-1)+months;
    const ny=Math.floor(idx/12),nm=idx-ny*12;
    const last=new Date(Date.UTC(ny,nm+1,0)).getUTCDate();
    return `${String(ny).padStart(4,'0')}-${String(nm+1).padStart(2,'0')}-${String(Math.min(d,last)).padStart(2,'0')}`;
  }
  // The default invoice due date: the same day next month (issued Oct 13 →
  // due Nov 13), not issued + 30 days (which lands on Nov 12).
  function invoiceDueDate(issued){return addMonths(issued,1);}
  root.DocumentDates={dateOnly,addDays,addMonths,invoiceDueDate};
})(window);

