function setQBMaterialQty(i,val){
  const m=window._qb.materials[i];if(!m)return;
  if(val===''||val==null){m.quantity='';_rollLengthFromQty(m);qbFastRecalc();return;}
  const v=Number(val);
  const cov=Number(m.coveragePerUOM)||0;
  // The epsilon keeps an exact carton multiple (522.94 = 22 × 23.77) from
  // reading as 22.000000000000004 and gaining a 23rd carton when re-entered.
  if(cov>1&&v>0){const cartons=Math.ceil(v/cov-1e-9);m.quantity=Math.round(cartons*cov*100)/100;}
  else{m.quantity=v;}
  _rollLengthFromQty(m);
  qbFastRecalc();
}

index:fn:_qbInchFrac.code:
function _qbInchFrac(dec){
  if(dec==null)return '';
  const sixteenths=Math.round(Number(dec)*16);
  if(sixteenths<=0)return '';
  const whole=Math.floor(sixteenths/16);
  let frac=sixteenths-whole*16;
  if(frac===0)return whole>0?String(whole):'';
  let n=frac,d=16;
  while(n%2===0){n/=2;d/=2;}
  return (whole>0?whole+' ':'')+n+'/'+d;
}

