function _rollLengthFromQty(m){
  if(!_isRolledLine(m)||!_rollQtyIsSqYd(m))return false;
  const q=Number(m.quantity)||0;
  if(!(q>0)){m.lengthFt='';m.lengthIn='';m.linearFt='';return true;}
  const n=_rollInchesFor(q,_rollEnsureWidth(m));if(!n)return false;
  m.lengthFt=Math.floor(n/12);m.lengthIn=n%12;m.linearFt=Math.round(n/12*100)/100;
  return true;
}

