function _rollDimsApply(p,m){
  const el=id=>document.getElementById(p+'-rd-'+id);
  const num=id=>Number((el(id)||{}).value)||0;
  const w=num('wft')+num('win')/12;const lf=num('lft'),li=num('lin');
  const typed=!!(el('lft')&&el('lft').dataset.typed==='1');
  if(w>0){m.rollWidth=Math.round(w*1000)/1000;delete m.rollWidthAssumed;}
  if(!typed&&Number(m.quantity)>0&&_rollQtyIsSqYd(m)&&_rollLengthFromQty(m))return 'qty';
  m.lengthFt=lf>0?lf:'';m.lengthIn=li>0?li:'';
  return lf+li/12;
}

index:fn:qbApplyRollDimensions.code:
function qbApplyRollDimensions(i){
  const m=window._qb&&window._qb.materials[i];
  if(!m)return;
  const typedL=_rollDimsApply('qb',m);
  if(typedL!=='qty')qbRecalcRollQty(i);
  // Reverse-sync: if the source product / inventory item has no roll length
  // recorded yet, save a length typed here back to them (matched by mat #)
  // so it prefills automatically next time this carpet is quoted.
  const _L=typedL==='qty'?0:typedL;
  if(_L>0&&m.matNum){
    const _rl=Math.round(_L*1000)/1000;let _n=0;
    (data.productList||[]).forEach(p=>{if(p.matNum===m.matNum&&!(Number(p.rollLength)>0)){p.rollLength=_rl;_n++;}});
    (data.inventory||[]).forEach(it=>{if(it.matNum===m.matNum&&!(Number(it.rollLength)>0)){it.rollLength=_rl;_n++;}});
    m.rollLength=_rl;
    if(_n){try{saveData();}catch(_){}showToast('📐 Roll length '+_rl.toFixed(2)+" ft saved to the product for next time",'info');}
  }
  closeModal();
  renderView();
}

