function qbFastRecalc(){if(typeof _refreshTotalsRail==='function')setTimeout(_refreshTotalsRail,0);if(typeof _refreshTotalsHeaderRow==='function')setTimeout(_refreshTotalsHeaderRow,0);if(typeof _refreshChecklistRail==='function')setTimeout(_refreshChecklistRail,0);
