function qbMcIsChosen(qb, sIdx, type, globalIdx){
  // Returns true iff the given (type,globalIdx) row in MC section sIdx
  // is the current chosen row. Returns null when the section isn't MC
  // (i.e. callers should treat null as "not applicable, render normally").
  const sec = qb && qb.sections && qb.sections[sIdx];
  if(!sec || !sec.multipleChoice) return null;
  const want = qbMcChosenRowKey(qb, sIdx);
  if(!want) return false;
  const local = qbMcSectionLocalIdx(qb, sIdx, type, globalIdx);
  if(local < 0) return false;
  return want === (type+'-'+local);
}

