function qbMcChosenRowKey(qb, sIdx){
  // Resolution order:
  //   1. sec.chosenRowKey         (admin pre-approval or applied customer pick)
  //   2. saved selectedOptions[]  (customer pick not yet applied)
  //   3. first row in section     (sensible default)
  const sec = qb && qb.sections && qb.sections[sIdx];
  if(!sec || !sec.multipleChoice) return null;
  if(sec.chosenRowKey) return String(sec.chosenRowKey);
  if(qb && qb.editId){
    const sq = getQuote(qb.editId);
    if(sq && Array.isArray(sq.selectedOptions)){
      const m = sq.selectedOptions.find(function(o){return o && o.mode==='mc' && Number(o.idx)===sIdx;});
      if(m && m.rowKey) return String(m.rowKey);
    }
  }
  return qbMcDefaultRowKey(qb, sIdx);
}

index:fn:qbMcSectionLocalIdx.code:
function qbMcSectionLocalIdx(qb, sIdx, type, globalIdx){
  // Returns N for a 'mat-N' / 'lab-N' rowKey, or -1 if the row isn't in
  // this section. Iteration matches q.html (array order, not _order).
  const arr = type==='mat' ? (qb&&qb.materials)||[] : (qb&&qb.labors)||[];
  let n=0;
  for(let i=0;i<arr.length;i++){
    if((arr[i]&&arr[i]._section||0) !== sIdx) continue;
    if(i === globalIdx) return n;
    n++;
  }
  return -1;
}

index:fn:qbMcDefaultRowKey.code:
function qbMcDefaultRowKey(qb, sIdx){
  // Default pick when no customer or admin choice exists yet: the first
  // material in the section, else the first labor.
  const mats=(qb&&qb.materials)||[];
  for(let i=0;i<mats.length;i++){
    if((mats[i]&&mats[i]._section||0)===sIdx) return 'mat-0';
  }
  const labs=(qb&&qb.labors)||[];
  for(let i=0;i<labs.length;i++){
    if((labs[i]&&labs[i]._section||0)===sIdx) return 'lab-0';
  }
  return null;
}

