  const allLabs=(q&&q.labors)||[];
  const outMats=[];const outLabs=[];
  // Iterate per-section so MC row indices line up with the public page.
  const sIdxs=Array.from(new Set([].concat(
    allMats.map(function(m){return m._section||0;}),
    allLabs.map(function(l){return l._section||0;}),
    sections.map(function(_,i){return i;})
  )));
  sIdxs.forEach(function(sIdx){
    if(!cs.has(sIdx))return;
    const sec=sections[sIdx]||{};
    const secMats=allMats.filter(function(m){return (m._section||0)===sIdx;});
    const secLabs=allLabs.filter(function(l){return (l._section||0)===sIdx;});
    if(sec.multipleChoice && mcRow[sIdx]){
      const key=String(mcRow[sIdx]);
      const m=key.match(/^mat-(\d+)$/);const l=key.match(/^lab-(\d+)$/);
      if(m){const idx=Number(m[1]);if(secMats[idx])outMats.push(secMats[idx]);}
      else if(l){const idx=Number(l[1]);if(secLabs[idx])outLabs.push(secLabs[idx]);}
    } else {
      secMats.forEach(function(m){outMats.push(m);});
      secLabs.forEach(function(x){outLabs.push(x);});
