function applyCustomerSelectionToQuote(q){
  if(!q||!Array.isArray(q.sections))return;
  const selOpts=Array.isArray(q.selectedOptions)?q.selectedOptions:null;
  if(!selOpts||!selOpts.length)return;
  // Choice picks arrive as one entry PER selected member, so the whole group
  // has to be collected before anything is written. The per-entry loop this
  // replaces set isChoiceDefault=true on each pick in turn and false on every
  // other member of the group — so a customer who picked both options ended
  // up with only the last one live, and bought half of what they asked for.
  const picksByGroup={};
  selOpts.forEach(function(o){
    if(!o||o.mode!=='choice')return;
    const idx=Number(o.idx);
    const sec=q.sections[idx];if(!sec)return;
    const cg=String((sec.choiceGroup||'')).trim();if(!cg)return;
    if(!picksByGroup[cg])picksByGroup[cg]=[];
    if(picksByGroup[cg].indexOf(idx)<0)picksByGroup[cg].push(idx);
  });
  Object.keys(picksByGroup).forEach(function(cg){
    const picks=picksByGroup[cg].slice().sort(function(a,b){return a-b;});
    q.sections.forEach(function(ss,ii){
      if(!ss||String((ss.choiceGroup||'')).trim()!==cg)return;
      ss.isChoiceSelected=picks.indexOf(ii)>=0;
      // isChoiceDefault still names exactly ONE member — it is what decides
      // which option a fresh quote opens on, and what older records carry
      // instead of a selection set. Point it at the first option the customer
      // picked so both readings stay sensible.
      ss.isChoiceDefault=(ii===picks[0]);
    });
  });
  selOpts.forEach(function(o){
    if(!o||o.mode!=='mc'||!o.rowKey)return;
    const sec=q.sections[Number(o.idx)];if(!sec)return;
    sec.chosenRowKey=String(o.rowKey);
  });
  // The sections now describe what the customer actually bought, so the money
  // stored on the quote has to describe it too. The builder recalculates on
  // every render, so the edit screen was already right — but the Quotes list,
  // the stat cards, the dashboard and the notifications all read the stored
  // q.total, which was last written when the quote was still sitting on
  // option 1. Without this a "Choose One" quote where the customer picked the
  // second option reads as the first option's price everywhere but the editor.
  _refreshQuoteStoredTotals(q);
}

