index:fn:_resolveQuoteLeadToCustomer.code:
function _resolveQuoteLeadToCustomer(q){
  if(!q||!q.leadId)return (q&&q.customerId)||'';
  const leadId=q.leadId;
  // Converts if it has not converted yet, and returns the customer it already
  // became if it has. Null only when the lead record is gone entirely.
  let cId=_convertLeadToCustomer(leadId);
  // Lead record is gone already — the customer it became still knows about it.
  if(!cId){
    const prior=(data.customers||[]).find(c=>c&&c.convertedFromLeadId===leadId);
    cId=prior?prior.id:'';
  }
  // Nothing to attach to: the lead is gone and no customer claims it. Leave
  // q.leadId alone — clearing it would destroy the only remaining trace of
  // where this quote came from without putting anything in its place.
  if(!cId)return q.customerId||'';
  if(!q.customerId)q.customerId=cId;
  // The inline converter this replaces fell back to the quote's rep when the
  // lead had none; _convertLeadToCustomer only reads the lead, so keep it.
  const cu=getCustomer(cId);
  if(cu&&!cu.salesRepId&&q.salesRepId)cu.salesRepId=q.salesRepId;
  // Its quote is approved, so the lead is done — whether it converted just now
  // or was converted earlier and left behind on the board.
  const wasListed=(data.leads||[]).some(l=>l&&l.id===leadId);
  data.leads=(data.leads||[]).filter(l=>l&&l.id!==leadId);
  if(wasListed)addActivity('Lead removed from pipeline');
  q.leadId=null;
  return q.customerId||'';
}

index:fn:_nvCityHit.code:
function _nvCityHit(hay,city){
  const i=hay.indexOf(city);
  if(i<0)return false;
  const before=i===0?' ':hay[i-1];
  const after=i+city.length>=hay.length?' ':hay[i+city.length];
  return !/[a-z0-9]/.test(before)&&!/[a-z0-9]/.test(after);
}

index:fn:_nvCityCounty.code:
function _nvCityCounty(lower){
  const parts=lower.split(',').map(s=>s.trim()).filter(Boolean);
  const scopes=parts.length>1?[parts.slice(1).join(' , '),lower]:[lower];
  for(const hay of scopes){
    // Longest name wins, so "north las vegas" is never decided by "las vegas"
    // and "carson city" is never decided by a shorter neighbour.
    let best=null;
    for(const[city,county]of Object.entries(NV_CITY_COUNTY)){
      if(_nvCityHit(hay,city)&&(!best||city.length>best.city.length))best={city,county};
    }
    if(best)return best.county;
  }
  return null;
}

index:fn:getTaxRateFromAddress.code:
function getTaxRateFromAddress(address){
  if(!address)return null;
  const lower=String(address).toLowerCase();
  // 1) An explicit county name ("Lyon County") is authoritative.
  for(const county of Object.keys(NV_COUNTY_TAX)){if(county!=='carson city'&&lower.includes(county+' county'))return _nvTaxResult(county);}
  // 2) The town, matched on whole words in the town position. A written town
  // beats the ZIP on purpose: 89705 covers south Carson City AND the Douglas
  // County side of the valley, so "Carson City ... 89705" has to stay Carson
  // City. The ZIP is the fallback for when nobody wrote a town we know.
  const byCity=_nvCityCounty(lower);
  if(byCity)return _nvTaxResult(byCity);
  // 3) The ZIP. Scan right-to-left — the zip sits at the end of an
  // address, so a zip-looking house number earlier in it never wins.
  const zips=lower.match(/\b8[89]\d{3}\b/g)||[];
  for(let i=zips.length-1;i>=0;i--){const county=NV_ZIP_COUNTY[zips[i]]||NV_ZIP3_COUNTY[zips[i].slice(0,3)];if(county)return _nvTaxResult(county);}
  return null;
}

