function _leadTryMoveStage(leadId,newStatus,from){
  const l=getLead(leadId);if(!l||l.status===newStatus)return false;
  // Moving any lead into Site Survey Scheduled requires a date — the date is what moves it.
  if(newStatus==='site_survey_scheduled'&&!l.siteSurveyDate){showToast(from==='panel'?'📐 Set a site-survey date first — that auto-moves it here.':'📐 Set a site-survey date on the card first — that auto-moves it here.','warning');return false;}
  if(newStatus==='approved'){showToast('Approve the lead’s quote to move it to Approved.','warning');return false;}
  if(newStatus==='lost'){const ok=confirm(`Mark ${l.name} as Lost?`);if(!ok)return false;}
  changeLeadStatus(leadId,newStatus);
  return true;
}

