function setLeadSurveyDate(leadId,date){
  const l=getLead(leadId);if(!l)return;
  const d=(date||'').slice(0,10);
  if(!d){
    // Clearing the date moves the lead back to 'new' if it was scheduled.
    l.siteSurveyDate=null;
    if(l.status==='site_survey_scheduled'){l.status='new';l.stageChangedAt=_todayISO();}
    addActivity(`Lead ${l.number||l.name}: site-survey date cleared`);
    saveData();renderView();
    return;
  }
  l.siteSurveyDate=d;
  if(l.status==='new'||l.status==='site_survey_scheduled'){
    l.status='site_survey_scheduled';
    l.stageChangedAt=_todayISO();
  }
  addActivity(`Lead ${l.number||l.name}: site survey ${fmtDate(d)} (auto-moved to Site Survey Scheduled)`);
  // Create/refresh the survey task — replace any existing pending survey task for this lead
  if(Array.isArray(data.tasks)){
    data.tasks=data.tasks.filter(t=>!(t.linkType==='lead'&&t.linkId===l.id&&t.status!=='completed'&&/site survey:/i.test(t.title||'')));
  }
  if(typeof createTask==='function'){
    const due=new Date(d+'T17:00:00').toISOString();
    createTask({title:`Site survey: ${l.name}`,description:`Visit ${l.address||'(no address)'} to measure and assess the site.`,priority:'high',assignedUserId:l.salesRepId||'',dueDate:due,linkType:'lead',linkId:l.id});
  }
  saveData();showToast(`📐 Survey set for ${fmtDate(d)} · ${l.name} → Site Survey Scheduled`);if(typeof refreshLeadKanban==='function')refreshLeadKanban();else renderView();
}

index:fn:_runLeadAutoTransitions.code:
function _runLeadAutoTransitions(){
  if(!data.leads)return;
  const today=_todayISO();
  let moved=0;
  data.leads.forEach(l=>{
    if(l.status!=='site_survey_scheduled')return;
    if(!l.siteSurveyDate)return;
    if(l.siteSurveyDate>today)return;
    l.status='send_quote';
    l.stageChangedAt=today;
    addActivity(`Lead ${l.number||l.name} auto-moved to Send Quote (survey date passed)`);
    // Close out the now-finished 'Site survey:' task — otherwise it stays
    // open, gains overdue score daily, and permanently outranks the new
    // 'Send quote' task in the Follow-Up Queue's one-row-per-lead dedupe.
    (data.tasks||[]).forEach(t=>{
      if(t.linkType==='lead'&&t.linkId===l.id&&t.status!=='completed'&&/^site survey/i.test(t.title||'')){
        t.status='completed';t.completedAt=new Date().toISOString();t.updatedAt=t.completedAt;
      }
    });
    if(typeof createTask==='function'){
      const t=createTask({title:`Send quote to ${l.name}`,description:`Site survey on ${fmtDate(l.siteSurveyDate)} is complete. Build and send the quote.`,priority:'high',assignedUserId:l.salesRepId||'',dueDate:new Date(Date.now()+2*864e5).toISOString(),linkType:'lead',linkId:l.id});
    }
    moved++;
  });
  if(moved>0)saveData();
}

