function _onQuoteSentToCustomer(quote,channel){
  if(!quote||!quote.leadId)return;
  const l=getLead(quote.leadId);if(!l||l.status==='approved'||l.status==='lost')return;
  const today=_todayISO();
  if(l.status!=='follow_up'){
    l.status='follow_up';
    l.stageChangedAt=today;
    addActivity(`Lead ${l.number||l.name} → Follow-up (quote ${quote.number||''} sent via ${channel})`);
  }
  // Avoid duplicate task if one already exists for this lead+quote
  const existing=(data.tasks||[]).find(t=>t.linkType==='lead'&&t.linkId===l.id&&t.status!=='completed'&&/follow up/i.test(t.title||'')&&(t.description||'').includes(quote.number||'__none__'));
  if(!existing&&typeof createTask==='function'){
    const due=new Date(Date.now()+3*864e5).toISOString();
    createTask({title:`Follow up with ${l.name} on quote ${quote.number||''}`,description:`Quote ${quote.number||''} was sent via ${channel}. Reach out to confirm receipt and answer questions.`,priority:'medium',assignedUserId:l.salesRepId||'',dueDate:due,linkType:'lead',linkId:l.id});
  }
}

