function _ensureTaskForLeadStage(l,status){
  if(!l||!status)return;
  if(!Array.isArray(data.tasks))data.tasks=[];
  if(typeof createTask!=='function')return;
  const has=(pattern)=>data.tasks.some(t=>t.linkType==='lead'&&t.linkId===l.id&&t.status!=='completed'&&pattern.test(t.title||''));
  if(status==='site_survey_scheduled'&&!has(/^site survey:/i)){
    const due=l.siteSurveyDate?new Date(l.siteSurveyDate+'T17:00:00').toISOString():new Date(Date.now()+1*864e5).toISOString();
    createTask({title:`Site survey: ${l.name}`,description:l.siteSurveyDate?`Visit ${l.address||'(no address)'} to measure and assess the site.`:`Confirm a survey date with the customer and visit ${l.address||'(no address)'}.`,priority:'high',assignedUserId:l.salesRepId||'',dueDate:due,linkType:'lead',linkId:l.id});
  } else if(status==='send_quote'&&!has(/^send quote/i)){
    createTask({title:`Send quote to ${l.name}`,description:`Build and send the quote to ${l.name}.`,priority:'high',assignedUserId:l.salesRepId||'',dueDate:new Date(Date.now()+2*864e5).toISOString(),linkType:'lead',linkId:l.id});
  } else if(status==='follow_up'&&!has(/^follow up/i)){
    createTask({title:`Follow up with ${l.name}`,description:`Check in on the quote — confirm receipt, answer questions, push for a decision.`,priority:'medium',assignedUserId:l.salesRepId||'',dueDate:new Date(Date.now()+3*864e5).toISOString(),linkType:'lead',linkId:l.id});
  } else if(status==='new'&&!has(/schedule site survey/i)){
    createTask({title:`Schedule site survey with ${l.name}`,description:`No survey date set on this lead — call to book the visit.`,priority:'high',assignedUserId:l.salesRepId||'',dueDate:new Date(Date.now()+1*864e5).toISOString(),linkType:'lead',linkId:l.id});
  }
}

index:fn:_convertLeadToCustomer.code:
function _convertLeadToCustomer(leadId){
  const lead=getLead(leadId);if(!lead)return null;
  // Converted earlier but still listed (old pipeline-board approvals): the
  // lead is dropped when its quote is approved, so bring its notes over too.
  if(lead.convertedCustomerId){_carryLeadNotes(lead,getCustomer(lead.convertedCustomerId));return lead.convertedCustomerId;}
  const today=_todayISO();
  const cu={
    id:'c'+Date.now(),type:lead.type==='Property Management'||lead.type==='Builder'||lead.type==='Commercial'?lead.type:'Retail',
    name:lead.name||'',phone:lead.phone||'',email:lead.email||'',
    address:lead.address||'',source:lead.source||'',
    salesRepId:lead.salesRepId||'',
    customerSince:today,
    contacts:Array.isArray(lead.contacts)?JSON.parse(JSON.stringify(lead.contacts)):[],
    properties:[],notes:[],files:[],
    convertedFromLeadId:lead.id
  };
  if(cu.address){
    cu.properties.push({id:'p'+Date.now(),label:(isCustomerCompany&&isCustomerCompany(cu)?'Main Office':'Home'),address:cu.address,contactId:'',notes:lead.sqFt||'',primary:true});
  }
  _carryLeadNotes(lead,cu);
  data.customers.push(cu);
  lead.convertedCustomerId=cu.id;
  data.leads=(data.leads||[]).filter(l=>l.id!==leadId);
  addActivity(`Lead ${lead.number||lead.name} converted to customer`);
  return cu.id;
}

index:fn:_carryLeadNotes.code:
function _carryLeadNotes(lead,cu){
  if(!lead||!cu||!Array.isArray(lead.notes)||!lead.notes.length)return 0;
  if(!Array.isArray(cu.notes))cu.notes=[];
  const key=n=>n&&typeof n==='object'?(n.callId?'call:'+n.callId:'note:'+(n.date||'')+'|'+(n.text||'')):'raw:'+String(n);
  const have=new Set(cu.notes.map(key));
  const add=lead.notes.filter(n=>n!=null&&!have.has(key(n)));
  add.forEach(n=>cu.notes.push(JSON.parse(JSON.stringify(n))));
  return add.length;
}

