function leadKbColumnBodyHTML(colKey,leads,kbQ){
  if(leads.length===0)return `<div style="text-align:center;padding:20px;color:var(--gray);font-size:12px">${kbQ?'No matches in this column':'No leads — drop here'}</div>`;
  const today=_todayISO();
  const bucks={today:[],week:[],month:[],older:[]};
  leads.forEach(l=>{bucks[_leadAgeBucketKey(l,today)].push(l);});
  const big=leads.length>15;
  const coll=viewState.leadKbCollapsed||{};
  const isOpen=(key,def)=>{const k=colKey+':'+key;return coll[k]==null?def:!coll[k];};
  const bucket=(key,label,def)=>{const arr=bucks[key];if(arr.length===0)return '';const open=isOpen(key,def);return `<div class="kb-bucket ${open?'open':'collapsed'}"><div class="kb-bucket-h" onclick="toggleLeadKbBucket('${colKey}','${key}',${def?'true':'false'})"><span class="kb-bucket-arrow">▾</span>${label}<span class="kb-bucket-count">${arr.length}</span></div>${open?`<div class="kb-bucket-cards">${arr.map(leadKbCardHTML).join('')}</div>`:''}</div>`;};
  const lbl=_leadAgeBucketLabel;
  return bucket('today',lbl('today'),true)+bucket('week',lbl('week'),!big||bucks.today.length===0)+bucket('month',lbl('month'),!big)+bucket('older',lbl('older'),false);
}

