  const j=getJob(jobId); if(!j) return;
  const dateEl=document.getElementById('sched-date');
  const endEl=document.getElementById('sched-end');
  const instEl=document.getElementById('sched-installer');
  const date=dateEl?dateEl.value:'';
  const end=endEl?endEl.value:'';
  const installer=instEl?instEl.value:'';
  if(!date&&!end&&!installer){showToast('Pick the install dates or assign an installer','warning');return;}
  // The dates come as a pair — a start needs its end, an end needs its start —
  // and a bad range is refused before anything on the job is touched.
  const span=(date||end)?_jobInstallSpan(date,end):null;
  if(span&&span.error){showToast(span.error,'warning');return;}
  const prevDate=j.scheduledDate||'';
  const prevDur=Math.max(1,Number(j.durationDays)||1);
  const prevCrew=j.crew||'';
  j.scheduledDate=date;
  if(span)j.durationDays=span.days;
  j.crew=installer;
  // Date set → fully scheduled. Installer only → advance to ready_to_schedule so the WO is clearly waiting on a date.
  if(date){
    if(j.status==='ready_to_schedule'||j.status==='materials_ordered'||j.status==='order_materials')j.status='scheduled';
  }else if(installer&&j.status==='materials_ordered'){
    j.status='ready_to_schedule';
  }
  const crewName=installer?(((data.contractors||[]).find(c=>c.id===installer)||{}).name||installer):'';
  const when=date?_installRangeLabel(date,j.durationDays):'';
  if(prevDate!==date||(date&&prevDur!==j.durationDays)||prevCrew!==installer){
    if(date&&crewName)addActivity(`Job ${j.number} scheduled for ${when} with ${crewName}`);
    else if(date)addActivity(`Job ${j.number} scheduled for ${when}`);
    else if(crewName)addActivity(`Job ${j.number} installer set to ${crewName} (date TBD)`);
  }
  saveData(); closeModal(); updateBadges(); renderView();
  if(date&&crewName)showToast(`📅 ${j.number} scheduled for ${when} · ${crewName}`);
  else if(date)showToast(`📅 ${j.number} scheduled for ${when}`);
  else showToast(`👷 ${j.number}: ${crewName} assigned (no date yet)`);
}

index:fn:_matMaybeAdvance.code:
function _matMaybeAdvance(j){
  if(!j)return false;
  const ms=_jobMatState(j);
  if(!['order_materials','materials_ordered'].includes(j.status))return false;
  if(ms.total&&ms.ordered===ms.total){
    if(j.scheduledDate){j.status='scheduled';addActivity(`Job ${j.number} → Scheduled (materials ordered, date already set)`);}
    else{j.status='ready_to_schedule';addActivity(`Job ${j.number} → Ready to Schedule (all materials ordered)`);}
    return true;
  }
  if(ms.ordered>0&&j.status==='order_materials'){j.status='materials_ordered';return true;}
  return false;
}

