function _jobMatState(j){
  const lines=_jobMatLines(j);
  const ordered=lines.filter(_matLineOrdered).length;
  const inCount=lines.filter(_matLineIn).length;
  return {total:lines.length,ordered,inCount,allIn:lines.length>0&&inCount===lines.length,none:lines.length===0};
}

