function _advanceJobToReady(jobId){
  const j=getJob(jobId);if(!j)return;
  _woGroupJobs(_woGroupParent(j)).forEach(m=>{
    if(m.status!=='final_invoice')return;
    m.status='ready_to_be_paid';
    addActivity(`Job ${m.number} → Ready to be Paid (invoice paid in full)`);
  });
}

index:fn:_jobInstallSpan.code:
function _jobInstallSpan(start,end){
  const s=_dateOnly(start),e=_dateOnly(end);
  if(!s)return {error:e?'Pick a start date — the end date counts from it.':'Pick a start date.'};
  if(!e)return {error:'Pick an end date — the same day as the start for a one-day job.'};
  const diff=_isoDayDiff(s,e);
  if(diff==null)return {error:'That date could not be read.'};
  if(diff<0)return {error:`The end date (${fmtDate(e)}) is before the start (${fmtDate(s)}).`};
  if(diff+1>JOB_MAX_INSTALL_DAYS)return {error:`That is ${diff+1} days on site — ${JOB_MAX_INSTALL_DAYS} at most. Check the year.`};
  return {days:diff+1};
}

index:fn:_jobInstallEnd.code:
function _jobInstallEnd(j){
  const start=_dateOnly(j&&j.scheduledDate);
  if(!start)return null;
  const days=Math.max(1,Number(j&&j.durationDays)||1);
  // Local calendar math. Date.parse('YYYY-MM-DD') is UTC midnight, which in
  // Pacific time is the evening BEFORE — every end date came out a day early,
  // and the Final Invoice sweep would have closed jobs on their last day.
  const p=start.split('-').map(Number);
  return _isoDay(new Date(p[0],p[1]-1,p[2]+days-1));
}

index:fn:_woGroupInvoice.code:
function _woGroupInvoice(j,pred){
  if(!j)return null;
  const ok=pred||function(){return true;};
  const invs=data.invoices||[];
  const own=invs.find(function(i){return i&&i.jobId===j.id&&ok(i);});
  if(own)return own;
  const p=_woGroupParent(j);
  if(!p||p.id===j.id)return null;
  return invs.find(function(i){return i&&i.jobId===p.id&&ok(i);})||null;
}

index:fn:_woGroupJobs.code:
function _woGroupJobs(j){
  const p=_woGroupParent(j);
  if(!p)return [];
  const kids=(data.jobs||[]).filter(x=>x&&x.parentJobId===p.id)
    .sort((a,b)=>String(a.number||'').localeCompare(String(b.number||''),undefined,{numeric:true}));
  return [p].concat(kids);
}

index:fn:_woGroupPaidInFull.code:
function _woGroupPaidInFull(j){
  const ids=new Set(_woGroupJobs(j).map(x=>x.id));
  const invs=(data.invoices||[]).filter(i=>i&&ids.has(i.jobId)&&i.status!=='void');
  return invs.length>0&&invs.every(i=>i.status==='paid');
}

index:fn:_plAutoAdvanceSweep.code:
function _plAutoAdvanceSweep(){
  if(!data||!Array.isArray(data.jobs))return 0;
  const today=_todayISO();
  // A work order open in an editor is left alone — it moves on the next pass.
  const editing=_liveEditingId('jobs');
  let done=0,paid=0;
  data.jobs.forEach(j=>{
    if(!j||j.id===editing||(j.status!=='scheduled'&&j.status!=='in_progress'))return;
    const end=_jobInstallEnd(j);
    if(!end||end>=today)return;
    completeJob(j.id,{stay:true,auto:true,completedAt:end});
    done++;
  });
  data.jobs.forEach(j=>{
    if(!j||j.id===editing||j.status!=='final_invoice'||!_woGroupPaidInFull(j))return;
    const before=_woGroupJobs(j).filter(m=>m.status==='final_invoice').length;
    _advanceJobToReady(j.id);
    paid+=before;
  });
  if(done||paid)saveData();
  return done+paid;
}

