function submitOrderMaterials(){
  const st=window._omState;if(!st)return;
  const j=getJob(st.jobId);if(!j)return;
  const cu=getCustomer(j.customerId);
  const today=_todayISO();
  const twoWeeksOut=_isoDay(new Date(Date.now()+14*864e5));
  const selected=st.lines.filter(L=>L.selected&&L.qty>0);
  if(!selected.length){
    showToast('Tick at least one line to mark as ordered','warning');
    return;
  }
  if(selected.some(L=>!L.poNumber)){
    showToast('Every selected line needs a PO #','warning');
    return;
  }
  _ensureJobPOs();
  let createdPOs=0;
  selected.forEach(L=>{
    const po={
      id:'jpo_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),
      number:_nextJobPONumber(),
      jobId:j.id,jobNumber:j.number,
      customerId:cu?cu.id:'',customerName:cu?cu.name:'',
      createdAt:today,
      poNumber:L.poNumber,
      orderDate:L.orderDate||today,
      estimatedDelivery:L.estimatedDelivery||twoWeeksOut,
      productName:L.productName,matNum:L.matNum,style:L.style,color:L.color,vendor:L.vendor,
      uom:L.uom,
      qty:L.qty,
      cost:L.cost,
      totalCost:L.qty*L.cost,freight:Math.max(0,Math.round((Number(L.freight)||0)*100)/100),
      status:'ordered',
      orderedAt:today,
      receivedAt:null
    };
    data.jobPOs.push(po);createdPOs++;
    // If the matNum is already in inventory, append a child PO row so the on-order
    // qty shows in the inventory drilldown. Otherwise leave inventory alone —
    // markJobPOReceived will look the matNum up in productList and create both
    // the inventory item and the child PO row at receive time.
    const inv=L.matNum?(data.inventory||[]).find(x=>x.matNum===L.matNum):null;
    if(inv){
      if(!inv.pOs)inv.pOs=[];
      inv.pOs.push({id:'po_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),poNumber:L.poNumber,productName:L.productName,matNum:L.matNum,style:L.style,color:L.color,vendor:L.vendor,companyCost:L.cost,retailPrice:0,coverage:0,costUOM:L.uom,coverageUOM:L.uom,qtyOrdered:L.qty,onHand:0,allocated:0,jobId:j.id,jobNumber:j.number,orderDate:po.orderDate,estimatedDelivery:po.estimatedDelivery,receivedAt:null});
    }
    // Mark the material so it doesn't reappear in the OM modal next time.
    const mat=j.materials&&j.materials[L.idx];
    if(mat){
      mat.poNumber=L.poNumber;
      mat.poOrderDate=po.orderDate;
      mat.estimatedDelivery=po.estimatedDelivery;
      mat.poCreated=true;
      mat.allocatedFromInventory=false;
    }
  });
  // Only a job still in Materials moves. Adding a PO to a job that is already
  // scheduled used to knock it back to Materials Ordered, off the Scheduled
  // column. Every line now ordered carries it on (owner rule — _matMaybeAdvance).
  if(j.status==='order_materials')j.status='materials_ordered';
  addActivity(`Work Order ${j.number}: ${createdPOs} PO${createdPOs===1?'':'s'} marked as ordered`);
  const _omMoved=_matMaybeAdvance(j);
  saveData();
  window._omState=null;
  closeModal();
  showToast(`✓ ${createdPOs} PO${createdPOs===1?'':'s'} marked as ordered${_omMoved?` — ${j.number} → ${JOB_STATUS_LABELS[j.status]||j.status}`:''}`);
  renderView();
}

