function jcMarkGroupPaid(jobId){
  const j=_woGroupParent(getJob(jobId));if(!j)return;
  const fin=_jobGroupFinance(j);
  const early=fin.members.filter(m=>!['ready_to_be_paid','paid','complete'].includes(m.status));
  if(early.length){showToast(`Not ready — ${early.map(m=>m.number).join(', ')} still at ${JOB_STATUS_LABELS[early[0].status]||early[0].status}`,'error');return;}
  const waiting=fin.members.filter(m=>m.status==='ready_to_be_paid');
  if(!waiting.length){showToast('Already paid','info');return;}
  const label=waiting.length>1?`${waiting.length} work orders on this job`:waiting[0].number;
  // Commission is still payable on a Paid job — say so rather than let it look settled.
  const owed=_jcCommissionOwed(fin);
  if(!confirm(`Mark ${label} Paid?\n\nThis closes the job out: it leaves the Pipeline board and moves to Projects → Archive.${owed?'\n\nThe commission has not been paid out yet — it stays listed under Commission due.':''}`))return;
  const today=_todayISO();
  waiting.forEach(m=>{m.status='paid';m.paidAt=today;addActivity(`Job ${m.number} → Paid (marked in Job Costing)`);});
  saveData();showToast(`💰 ${label} marked Paid — moved to the Archive`);renderView();
}

