function acctRecordInvPayment(invId){
  const inv=getInvoice(invId);if(!inv)return;
  const amt=+document.getElementById('acct-pay-amt').value;
  if(!amt||amt<=0)return alert('Enter a valid amount');
  if(!inv.payments)inv.payments=[];
  inv.payments.push(_payWithCheckNo({amount:amt,method:document.getElementById('acct-pay-method').value,date:document.getElementById('acct-pay-date').value},'acct-'));
