  // moves to Ready to be Paid once the invoice is paid in full.
  if(inv.status==='paid'&&inv.jobId)_advanceJobToReady(inv.jobId);
  addActivity(`Payment ${fmt$(amt)} on ${inv.number}`);
  saveData();closeModal();showToast(`✓ Payment of ${fmt$(amt)} recorded on ${inv.number}`);renderView();
