function _lcFilterState(){
  const v=viewState||{};
  return {
    q:String(v.leadQ||'').trim().toLowerCase(),
    status:v.leadStatus||'all',
    type:v.leadCustType||'all',
    source:v.leadSource||'all',
    // '' is a real choice here (Unassigned), so only a missing value means all.
    rep:v.leadSalesRep==null?'all':String(v.leadSalesRep),
    age:v.leadAgeBucket||'all',
    bucket:v.leadBucket||'all',
    // Newest leads first unless a column header says otherwise.
    sort:v.leadSort||'age',
    dir:v.leadSortDir||(v.leadSort&&v.leadSort!=='age'?'desc':'asc')
  };
}

index:fn:_lcLocalDay.code:
function _lcLocalDay(v){
  const s=String(v||'');if(!s)return '';
  if(s.length<=10)return s.slice(0,10);
  const d=new Date(s);if(isNaN(d.getTime()))return s.slice(0,10);
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

index:fn:_lcLastTouch.code:
function _lcLastTouch(l,ctx){
  let day=_lcLocalDay(l.createdAt),what='Created';
  const take=(d,w)=>{d=_lcLocalDay(d);if(d&&(!day||d>day)){day=d;what=w;}};
  take(l.stageChangedAt,'Stage changed');
  (Array.isArray(l.notes)?l.notes:[]).forEach(n=>take(n&&n.date,'Note logged'));
  if(ctx&&ctx.callTouch[l.id])take(ctx.callTouch[l.id],'Call');
  return {day,what};
}

index:fn:_lcAgo.code:
function _lcAgo(day,today){
  if(!day)return '—';
  const d=daysBetween(day,today);
  if(isNaN(d))return '—';
  if(d<=0)return 'Today';
  if(d===1)return 'Yesterday';
  if(d<7)return d+'d ago';
  if(d<60)return Math.round(d/7)+'w ago';
  if(d<365)return Math.round(d/30)+'mo ago';
  return Math.floor(d/365)+'y ago';
}

index:fn:_lcInitials.code:
function _lcInitials(name){
  const s=String(name||'').trim();
  if(!/[A-Za-z]/.test(s))return '#';
  const w=s.split(/\s+/).map(x=>x.replace(/[^A-Za-z0-9]/g,'')).filter(Boolean);
  return ((w[0]||'').charAt(0)+(w.length>1?w[w.length-1].charAt(0):'')).toUpperCase()||'#';
}

index:fn:_lcMatchesSearch.code:
function _lcMatchesSearch(l,q,ctx){
  if(!q)return true;
  const rep=l.salesRepId&&ctx.repById[l.salesRepId];
  const notes=Array.isArray(l.notes)?l.notes:[];
  const contacts=Array.isArray(l.contacts)?l.contacts:[];
  const hay=[l.name,l.phone,l.email,l.address,l.address2,l.projectType,l.source,l.number,l.type,l.sqFt,rep&&rep.name]
    .concat(notes.map(n=>n&&n.text))
    .concat(contacts.map(c=>c&&[c.name,c.title,c.phone,c.email].join(' ')));
  if(hay.some(v=>v&&String(v).toLowerCase().includes(q)))return true;
  // Digits find a number however it was typed: "7755550134" finds "(775) 555-0134".
  const qd=q.replace(/\D/g,'');
  if(qd.length>=3&&/^[\d\s().+-]+$/.test(q))return [l.phone].concat(contacts.map(c=>c&&c.phone)).some(p=>String(p||'').replace(/\D/g,'').includes(qd));
  return false;
}

index:fn:_lcSortKey.code:
function _lcSortKey(l,col,ctx){
  switch(col){
    case 'number':return String(l.number||'').toLowerCase();
    case 'name':return String(l.name||'').toLowerCase();
    case 'phone':return String(l.phone||'').toLowerCase();
    case 'email':return String(l.email||'').toLowerCase();
    case 'status':{const i=LEAD_STATUSES.indexOf(l.status);return i<0?999:i;}
    case 'project':return String(l.projectType||'').toLowerCase();
    case 'source':return String(l.source||'').toLowerCase();
    case 'custType':return String(l.type||'').toLowerCase();
    case 'rep':{const r=l.salesRepId&&ctx.repById[l.salesRepId];return r?String(r.name||'').toLowerCase():'~';}
    case 'touch':return _lcLastTouch(l,ctx).day||'';
    case 'quoted':{const q=_lcLatestQuote(l,ctx);return q?(Number(q.total)||0):-1;}
    case 'age':return daysBetween(l.createdAt,ctx.today);
    default:return '';
  }
}

