function _lcFilterLeads(all,st,ctx){
  const today=ctx.today;
  const out=all.filter(l=>{
    if(st.status!=='all'&&l.status!==st.status)return false;
    if(st.type!=='all'&&(l.type||'')!==st.type)return false;
    if(st.source!=='all'&&(l.source||'')!==st.source)return false;
    if(st.rep!=='all'&&(l.salesRepId||'')!==st.rep)return false;
    if(st.age!=='all'){const d=daysBetween(l.createdAt,today);if(st.age==='week'&&d>7)return false;if(st.age==='month'&&d>30)return false;if(st.age==='old'&&d<=30)return false;}
    if(st.bucket!=='all'&&_leadAgeBucketKey(l,today)!==st.bucket)return false;
    return _lcMatchesSearch(l,st.q,ctx);
  });
  out.sort((a,b)=>{const av=_lcSortKey(a,st.sort,ctx),bv=_lcSortKey(b,st.sort,ctx);let cmp=0;if(typeof av==='number'&&typeof bv==='number')cmp=av-bv;else if(av<bv)cmp=-1;else if(av>bv)cmp=1;return st.dir==='asc'?cmp:-cmp;});
  return out;
}

