function _lcQuickAdd(){
  const v=_lcQuickVals();
  if(!v.name||!v.phone){showToast('Name and phone are required to add a lead.','warning');const f=document.getElementById(v.name?'lcq-phone':'lcq-name');if(f)f.focus();return;}
  if(window._lcDupBypass){window._lcDupBypass=false;}
  else{const d=_findDuplicates({name:v.name,phone:v.phone,email:v.email,address:v.address});if(d.length){_dupGuardPrompt('lead',d,function(){window._lcDupBypass=true;_lcQuickAdd();});return;}}
  const nl=_createLeadRecord(v);
  // Clear the search and filters so the new lead is on screen, selected.
  Object.assign(viewState,{leadView:'list',leadQ:'',leadStatus:'all',leadCustType:'all',leadSource:'all',leadSalesRep:'all',leadAgeBucket:'all',leadBucket:'all',leadSel:nl.id});
  window._lcEditId=null;
  showToast(`✓ ${nl.number} added — ${nl.name}`);
