function _createLeadRecord(v){
const name=String(v.name||'').trim(),phone=String(v.phone||'').trim();
data.counters.lead++;const num='LD-'+String(data.counters.lead).padStart(3,'0');const today=_todayISO();const salesRepId=v.salesRepId||'';const leadType=v.type||'Retail';const leadContacts=isCustomerCompany(leadType)&&Array.isArray(v.contacts)?JSON.parse(JSON.stringify(v.contacts)):[];const surveyDate=String(v.siteSurveyDate||'').slice(0,10)||null;const status=surveyDate?'site_survey_scheduled':'new';const noteText=String(v.noteText||'').trim();const newLead={id:'l'+Date.now(),number:num,name,phone,email:String(v.email||'').trim(),address:String(v.address||'').trim(),address2:String(v.address2||'').trim(),projectType:v.projectType||'',sqFt:String(v.sqFt||'').trim(),source:v.source||'',status,salesRepId,type:leadType,contacts:leadContacts,siteSurveyDate:surveyDate,notes:noteText?[{text:noteText,date:today}]:[],followUpDate:null,createdAt:today,stageChangedAt:today,convertedCustomerId:null};data.leads.push(newLead);addActivity(`New lead ${num} — ${name}`);
// Auto-create the right follow-up task based on whether a survey date was set.
if(typeof createTask==='function'){
  if(surveyDate){
    const due=new Date(surveyDate+'T17:00:00').toISOString();
    createTask({title:`Site survey: ${name}`,description:`Visit ${newLead.address||'(no address)'} to measure and assess the site.`,priority:'high',assignedUserId:salesRepId||'',dueDate:due,linkType:'lead',linkId:newLead.id});
  } else {
    const due=new Date(Date.now()+1*864e5).toISOString();
