  const repOpts=`<option value="all">Rep</option><option value="" ${st.rep===''?'selected':''}>Unassigned</option>`+reps.map(r=>`<option value="${_fesc(r.id)}" ${st.rep===r.id?'selected':''}>${_fesc(r.name||'')}</option>`).join('');
  const ageOpts=`<option value="all">Age</option><option value="week" ${st.age==='week'?'selected':''}>≤ 1 week</option><option value="month" ${st.age==='month'?'selected':''}>≤ 1 month</option><option value="old" ${st.age==='old'?'selected':''}>&gt; 1 month</option>`;
