  const head=`<div class="lc-p-head">${_lcAvatarHTML(l,true)}<div class="lc-p-title"><div class="lc-p-name">${esc(l.name||'')}</div><div class="lc-p-sub">${esc(l.number||'')}${ct?` · ${biz?'🏢':'👤'} ${esc(ct)}`:''}</div></div><button type="button" class="btn btn-outline btn-sm" onclick="navigate('lead-detail',{id:'${id}'})" title="Open the full lead page">Open ↗</button></div>`;
  const flags=(fu==='overdue'?'<span class="badge-pill badge-red" title="A follow-up is overdue on this lead">📅 Follow-up overdue</span>':'')
    +(stale?`<span class="badge-pill badge-amber" title="No stage change in ${daysStage} days">⚠ Stale ${daysStage}d</span>`:'');
  const stageLine=`<div class="lc-p-stage"><span class="badge-pill badge-${col}">${esc(LEAD_STATUS_LABELS[l.status]||l.status||'')}</span><span class="lc-muted">${daysStage}d in stage · ${isNaN(daysLead)?'—':daysLead+'d'} as lead</span>${flags}</div>`;
  const contactLine=`<div class="lc-p-contact">${l.email?`<a href="mailto:${esc(l.email)}">✉️ ${esc(l.email)}</a>`:'<span class="lc-muted">✉️ No email</span>'}<span class="lc-muted">·</span>${l.phone?`<a href="tel:${esc(l.phone)}">📞 ${esc(l.phone)}</a>`:'<span class="lc-muted">📞 No phone</span>'}</div>`;
  const actions=`<div class="lc-p-actions">${l.phone?`<a href="tel:${esc(l.phone)}" class="btn btn-primary btn-sm">📞 Call</a>`:''}${l.address?`<a href="${maps(l.address)}" target="_blank" rel="noopener" class="btn btn-outline btn-sm">📍 Directions</a>`:''}<button type="button" class="btn btn-outline btn-sm" onclick="window._qb=null;navigate('quote-builder',{leadId:'${id}',_reset:true})">📝 New Quote</button><button type="button" class="btn btn-outline btn-sm" onclick="openLeadShareMenu('${id}',event)" title="Share this lead">🔗 Share ▾</button>${converted?`<button type="button" class="btn btn-outline btn-sm" onclick="navigate('customer-detail',{id:'${l.convertedCustomerId}'})" title="Open the linked customer profile">👤 Customer</button>`:''}</div>`;

  // Approved is shown in the row but is not a button: a lead is never approved
  // by hand — it gets there when one of its quotes is approved.
  const stageBtns=LEAD_STATUSES.map(s=>{
    const on=l.status===s;
