    if(s==='approved')return `<span class="lc-stage-btn lc-stage-auto${on?' on':''}" data-stage="${s}" ${style} title="${on?'Current stage — reached when a quote was approved':'Reached automatically when one of this lead’s quotes is approved'}">${label}</span>`;
    const tip=on?'Current stage':(s==='site_survey_scheduled'&&!l.siteSurveyDate)?'Set a site-survey date below — that moves it here':'Move to '+(LEAD_STATUS_LABELS[s]||s);
    return `<button type="button" class="lc-stage-btn${on?' on':''}" data-stage="${s}" ${style} ${on?'aria-pressed="true"':''} title="${esc(tip)}" onclick="_lcMoveStage('${id}','${s}')">${label}</button>`;
  }).join('');
  const dates=`<div class="lc-dates"><label class="lc-date"><span>📐 Site Survey Date</span><input type="date" id="lc-survey-date" value="${esc(l.siteSurveyDate||'')}" onchange="setLeadSurveyDate('${id}',this.value)" title="Setting a date moves a New lead to Site Survey Scheduled; it moves on to Send Quote once the date passes"></label><label class="lc-date"><span>📅 Follow-up Date</span><input type="date" id="lc-followup-date" value="${esc(l.followUpDate||'')}" onchange="_lcSetFollowUp('${id}',this.value)" title="Surfaces this lead in your Follow-Up Queue on that day"></label></div>`;
  const stageSec=sec('lc-sec-stage','Stage',null,'',`<div class="lc-stage-btns">${stageBtns}</div>${dates}`);

  const noteList=notes.length?notes.slice().reverse().map(n=>`<div class="lc-note"><div class="lc-note-d">${n&&n.date?esc(fmtDate(n.date)):''}</div><div class="lc-note-t">${esc((n&&n.text)||'')}</div></div>`).join(''):'<div class="lc-empty">No notes yet — log your first touch.</div>';
  const notesSec=sec('lc-sec-notes','Notes',notes.length,'',`<textarea id="lead-note-input" class="lc-note-in" rows="2" placeholder="Called, emailed, what they said… (Ctrl+Enter to add)" onkeydown="if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();_lcAddNote('${id}')}"></textarea><div class="lc-note-btns"><button type="button" class="btn btn-primary btn-sm" onclick="_lcAddNote('${id}')">Add note</button></div><div class="lc-notes">${noteList}</div>`);

  const access=String(l.sqFt||'');
  const row=(k,v)=>`<dt>${k}</dt><dd>${v}</dd>`;
  const detailsBody=editing?_lcEditFormHTML(l):`<dl class="lc-dl">`
    +row('Lead Type',ct?`${biz?'🏢':'👤'} ${esc(ct)}`:dash)
    +row('Address',l.address?`<a href="${maps(l.address)}" target="_blank" rel="noopener">${esc(l.address)}</a>`:dash)
    +row('Suite / Unit / Apt',l.address2?esc(l.address2):dash)
    +row('Access Details',access?`<div class="lc-clamp">${esc(access)}</div><button type="button" class="lc-link lc-more" onclick="_lcToggleMore(this)">More</button>`:dash)
    +row('Project Type',l.projectType?esc(l.projectType):dash)
