  const detailsSec=sec('lc-sec-details','Details',null,editing?'':`<button type="button" class="lc-link" onclick="_lcEditStart('${id}')">✏️ Edit</button>`,detailsBody);

  const contactsBody=contacts.length?contacts.map(cn=>`<div class="lc-contact"><div class="lc-contact-main"><div class="lc-contact-n">${cn.primary?'<span class="lc-star" title="Primary contact">★</span> ':''}${esc(cn.name||'')}${cn.title?` <span class="lc-muted">— ${esc(cn.title)}</span>`:''}</div><div class="lc-sub">${[cn.phone?`<a href="tel:${esc(cn.phone)}">${esc(cn.phone)}</a>`:'',cn.email?`<a href="mailto:${esc(cn.email)}">${esc(cn.email)}</a>`:''].filter(Boolean).join(' · ')||'<span class="lc-muted">No phone or email</span>'}</div></div><div class="lc-contact-act"><button type="button" class="lc-link" onclick="openLeadEditContactModal('${id}','${cn.id}')">Edit</button><button type="button" class="lc-link lc-link-danger" onclick="deleteLeadContact('${id}','${cn.id}')" title="Delete this contact" aria-label="Delete this contact">✕</button></div></div>`).join('')
    :`<div class="lc-empty">${biz?'No contacts yet — add the property manager, accountant or decision-maker.':'No other contacts.'}</div>`;
  const contactsSec=sec('lc-sec-contacts','Contacts',contacts.length,`<button type="button" class="lc-link" onclick="openLeadNewContactModal('${id}')">+ Add</button>`,contactsBody);

  const taskBody=tasks.length?tasks.map(t=>{const due=t.dueDate?String(t.dueDate).slice(0,10):'';const od=!!due&&due<today;return `<div class="lc-task"><button type="button" class="lc-task-ck" title="Mark complete" aria-label="Mark complete" onclick="completeTask('${t.id}')">✓</button><button type="button" class="lc-task-t" onclick="openTaskDetailModal('${t.id}')" title="${esc(t.title||'')}">${esc(t.title||'Task')}</button><span class="lc-task-d${od?' od':''}">${due?esc(fmtDate(due)):'No due date'}</span></div>`;}).join(''):'<div class="lc-empty">No open tasks.</div>';
  const tasksSec=sec('lc-sec-tasks','Open Tasks',tasks.length,'',taskBody);

  const qDate=q=>q.createdAt?fmtDate((typeof DocumentDates!=='undefined'&&DocumentDates.dateOnly)?DocumentDates.dateOnly(q.createdAt):String(q.createdAt).slice(0,10)):'';
  const quoteBody=quotes.length?quotes.map(q=>`<button type="button" class="lc-qrow" onclick="navigate('quote-detail',{id:'${q.id}'})"><span class="lc-q-n">${esc(q.number||'—')}</span><span class="lc-muted">${esc(qDate(q))}</span><span class="lc-q-t">${fmt$(Number(q.total)||0)}</span>${statusBadge(q.status,QUOTE_STATUS_COLORS)}</button>`).join(''):'<div class="lc-empty">No quotes yet.</div>';
  const quotesSec=sec('lc-sec-quotes','Quotes',quotes.length,`<button type="button" class="lc-link" onclick="window._qb=null;navigate('quote-builder',{leadId:'${id}',_reset:true})">+ New Quote</button>`,quoteBody);

  const sampleBody=samples.length?samples.slice(0,3).map(s=>`<div class="lc-call">${getSampleStatusBadge(getSampleStatus(s))}<span>${esc(s.productName||'—')}</span><span class="lc-muted">${s.returnedDate?'returned '+esc(fmtDate(s.returnedDate)):s.expectedReturn?'due '+esc(fmtDate(s.expectedReturn)):''}</span></div>`).join('')+(samples.length>3?`<div class="lc-empty">+ ${samples.length-3} more on the lead page</div>`:''):'<div class="lc-empty">No samples checked out.</div>';
  const samplesSec=sec('lc-sec-samples','🎨 Samples',samples.length,`<button type="button" class="lc-link" onclick="openNewSampleCheckoutPrefilled('lead','${id}')">+ Check Out</button>`,sampleBody);

  const gist=r=>String(r.caller_summary||'')||((r.summary&&Array.isArray(r.summary.summary))?r.summary.summary.join(' '):'');
  const callBody=!callsLoaded?`<div class="lc-empty">${window._callLog&&window._callLog.loading?'Loading the call history…':'Open the Call Log above to load the call history.'}</div>`
    :calls.length?calls.slice(0,3).map(r=>`<div class="lc-call">${_callLogDirBadge(r)}<span class="lc-muted">${esc(_commsFmtDT(r.occurred_at||r.created_at))}</span>${gist(r)?`<div class="lc-call-g">${esc(gist(r).slice(0,160))}</div>`:''}</div>`).join('')
    :'<div class="lc-empty">No calls on record for this number.</div>';
  const callsSec=sec('lc-sec-calls','📞 Calls',callsLoaded?calls.length:null,`<button type="button" class="lc-link" onclick="navigate('lead-detail',{id:'${id}',tab:'calls'})">Calls &amp; messages →</button>`,callBody);

  const tabs=[['contacts','Contacts',contacts.length],['quotes','Quotes',quotes.length],['samples','🎨 Samples',samples.length],['interactions','👁 Interactions',interactions],['actions','Actions',null],['calls','📞 Calls',null],['messages','💬 Messages',null],['notes','Notes',notes.length]];
  const moreSec=sec('lc-sec-more','Lead Page',null,'',`<div class="lc-more-links">${tabs.map(([t,lbl,n])=>`<a href="#" onclick="event.preventDefault();navigate('lead-detail',{id:'${id}',tab:'${t}'})">${lbl}${n!=null?` (${n})`:''}</a>`).join('')}</div>`);

  const foot=`<div class="lc-p-foot"><button type="button" class="btn btn-outline btn-sm lc-del" onclick="deleteLead('${id}')" title="Moves to the Recycle Bin — recoverable for 30 days">🗑️ Delete lead</button></div>`;
  return head+stageLine+contactLine+actions+stageSec+notesSec+detailsSec+contactsSec+tasksSec+quotesSec+samplesSec+callsSec+moreSec+foot;
}

