function _lcKeyNav(ev){
  if(ev.key!=='ArrowDown'&&ev.key!=='ArrowUp')return;
  const ids=[].slice.call(document.querySelectorAll('#lc-table-wrap tr.lc-row')).map(tr=>tr.getAttribute('data-id'));
  if(!ids.length)return;
  ev.preventDefault();
  const i=ids.indexOf(viewState.leadSel);
  const n=ev.key==='ArrowDown'?Math.min(ids.length-1,i+1):Math.max(0,i<0?0:i-1);
  if(ids[n]&&ids[n]!==viewState.leadSel){_lcSelect(ids[n]);_lcRevealSelected();}
}

index:fn:_findDuplicates.code:
function _findDuplicates(vals,skipId){
  const ph=_dupPhone(vals&&vals.phone), em=_dupEmail(vals&&vals.email);
  const nm=_dupText(vals&&vals.name), ad=_dupText(vals&&vals.address);
  const out=[];
  const scan=(list,kind)=>{(list||[]).forEach(r=>{
    if(!r||!r.id||r.id===skipId)return;
    if(kind==='lead'&&r.convertedCustomerId)return;   // already became a customer
    const reasons=[];
    if(ph&&_dupPhone(r.phone)===ph)reasons.push('same phone');
    if(em&&_dupEmail(r.email)===em)reasons.push('same email');
    const sameName=!!nm&&_dupText(r.name)===nm;
    if(sameName&&ad&&_dupText(r.address)===ad)reasons.push('same name and address');
    else if(sameName)reasons.push('same name');
    if(!reasons.length)return;
    // A shared name alone is weak — plenty of real people share one. A phone,
    // an email, or a name AND address together is worth stopping for.
    out.push({kind:kind,rec:r,reasons:reasons,strong:reasons.some(x=>x!=='same name')});
  });};
  scan(data.customers,'customer');
  scan(data.leads,'lead');
  return out.sort((a,b)=>(b.strong?1:0)-(a.strong?1:0)).slice(0,6);
}

