function updateLeadFollowUp(id,date){const l=getLead(id);if(!l)return;l.followUpDate=date;
// The Follow-Up Queue is built from lead-linked tasks, so make the helper
// text true: keep one open "Follow up with …" task per lead in sync with
// this date (create on set, retarget on change, complete on clear).
try{
  const open=(data.tasks||[]).find(t=>t.linkType==='lead'&&t.linkId===l.id&&t.status!=='completed'&&/^follow up with /i.test(t.title||''));
  if(date){
    const dueIso=new Date(date+'T17:00:00').toISOString();
    if(open){open.dueDate=dueIso;open.updatedAt=new Date().toISOString();}
    else if(typeof createTask==='function')createTask({title:`Follow up with ${l.name||l.number||'lead'}`,description:'Scheduled from the lead’s Follow-up Date field',priority:'medium',assignedUserId:l.salesRepId||'',dueDate:dueIso,linkType:'lead',linkId:l.id});
  }else if(open){open.status='completed';open.completedAt=new Date().toISOString();open.updatedAt=open.completedAt;}
  if(typeof _lfRefreshFollowupBadge==='function')_lfRefreshFollowupBadge();
}catch(e){console.warn('follow-up task sync:',e);}
saveData()}

