function dayNum(s) {
    if (!s) return null;
    var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s));
    if (!m) { var d = new Date(s); if (isNaN(d)) return null; return Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 864e5); }
    return Math.floor(Date.UTC(+m[1], +m[2] - 1, +m[3]) / 864e5);
  }

mobile:fn:ago.code:
function ago(s) {
    var d = daysSince(s); if (d == null) return '';
    if (d <= 0) return 'today'; if (d === 1) return '1d';
    if (d < 14) return d + 'd'; if (d < 60) return Math.round(d / 7) + 'w';
    return Math.round(d / 30) + 'mo';
  }

mobile:fn:whenDay.code:
function whenDay(s) {
    var n = dayNum(s); if (n == null) return '';
    var t = todayNum(), diff = n - t;
    if (diff === 0) return 'Today'; if (diff === 1) return 'Tomorrow'; if (diff === -1) return 'Yesterday';
    var d = new Date(n * 864e5);
    var opts = { weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC' };
    if (Math.abs(diff) > 180) opts.year = 'numeric';
    return d.toLocaleDateString('en-US', opts);
  }

