function leadRow(l, extra, noChip) {
    var st = stage(l.status);
    var a = ago(l.createdAt);
    var bits = [l.projectType, l.source, a && (a === 'today' ? 'today' : a + ' ago')].filter(Boolean);
    // The date that matters for the stage it is in.
    if (l.status === 'site_survey_scheduled' && l.siteSurveyDate) bits = ['Survey ' + whenDay(l.siteSurveyDate), streetOf(l.address)].filter(Boolean);
    else if (l.status === 'follow_up' && l.followUpDate) bits = ['Follow up ' + whenDay(l.followUpDate)].concat(l.projectType ? [l.projectType] : []);
    var stale = false; try { stale = isLeadStale(l); } catch (_) { }
    return '<div class="m-row">' +
      '<button type="button" class="m-row-main" onclick="M.go(\'lead\',\'' + js(l.id) + '\')">' + avatar(l.name, st.color) +
      '<span class="m-row-txt"><b>' + esc(l.name || 'Unnamed lead') + (stale ? '<em class="m-stale" title="Sitting in this stage too long">' + ic('flame') + '</em>' : '') + '</b><small>' + esc(extra || bits.join(' · ')) + '</small></span>' + (noChip ? '' : stageChip(l.status)) + '</button>' +
      (l.phone ? '<a class="m-row-call" href="' + esc(telHref(l.phone)) + '" aria-label="Call ' + esc(l.name) + '">' + ic('phone') + '</a>' : '') +
      '</div>';
  }

