function leadListHtml() {
    var q = ui.leadQ.trim().toLowerCase(), f = ui.leadFilter;
    var list = myLeads().filter(function (l) {
      var s = l.status === 'quote_sent' ? 'send_quote' : l.status;
      if (f === 'active') { if (s === 'approved' || s === 'lost') return false; }
      else if (s !== f) return false;
      if (!q) return true;
      return [l.name, l.phone, l.email, l.address, l.number, l.source, l.projectType].join(' ').toLowerCase().indexOf(q) >= 0;
    }).sort(function (a, b) { return String(b.createdAt || '').localeCompare(String(a.createdAt || '')) || String(b.number || '').localeCompare(String(a.number || ''), 'en', { numeric: true }); });
    if (!list.length) return q ? empty('search', 'No matches', 'Nothing matches “' + esc(q) + '”.') : empty('inbox', 'No leads here', 'New leads from the website, calls and walk-ins land here.', '<button type="button" class="m-btn primary" onclick="M.newLead()">' + ic('user-plus') + 'Add a lead</button>');
    return list.map(function (l) { return leadRow(l); }).join('');
  }

mobile:fn:scrLead.code:
function scrLead(id) {
    var l = getLead(id);
    if (!l) return missing('Lead', 'leads');
    var st = stage(l.status);
    var tnum = todayNum();
    var quotes = (data.quotes || []).filter(function (q) { return q && q.leadId === l.id; });
    // Pipeline ribbon — tap a step to move the lead there.
    var curIdx = PIPE.indexOf(l.status === 'quote_sent' ? 'send_quote' : l.status);
    var ribbon = '<div class="m-pipe" role="group" aria-label="Stage">' + PIPE.map(function (s, i) {
      var cls = i < curIdx ? 'done' : i === curIdx ? 'on' : '';
      return '<button type="button" class="m-pipe-s ' + cls + ' c-' + stage(s).color + '" onclick="M.leadStage(\'' + js(l.id) + '\',\'' + s + '\')"' + (i === curIdx ? ' aria-current="step"' : '') + '><i></i><span>' + esc(stage(s).short) + '</span></button>';
    }).join('') + '</div>';
    if (l.status === 'lost' || l.status === 'approved') ribbon = '<div class="m-banner c-' + st.color + '">' + ic(l.status === 'lost' ? 'circle-x' : 'circle-check') + '<span>This lead is <b>' + esc(st.label.toLowerCase()) + '</b>.</span>' + (l.status === 'lost' ? '<button type="button" class="m-link" onclick="M.leadStage(\'' + js(l.id) + '\',\'new\')">Reopen</button>' : '') + '</div>';

    // The one thing to do next, by stage.
    var next = '';
    if (l.status === 'new') {
      next = nextCard('calendar', 'Schedule the site survey', l.siteSurveyDate ? 'Planned ' + whenDay(l.siteSurveyDate) : 'Call ' + esc(firstName(l.name)) + ' and pick a day to measure.',
        '<button type="button" class="m-btn primary" onclick="M.surveyDate(\'' + js(l.id) + '\')">' + ic('calendar') + 'Pick a date</button>' +
        (l.phone ? '<a class="m-btn ghost" href="' + esc(telHref(l.phone)) + '">' + ic('phone') + 'Call</a>' : ''));
    } else if (l.status === 'site_survey_scheduled') {
      var dd = l.siteSurveyDate ? dayNum(l.siteSurveyDate) - tnum : null;
      next = nextCard('calendar-check', l.siteSurveyDate ? 'Site survey ' + whenDay(l.siteSurveyDate) : 'Site survey — no date', (dd != null && dd < 0) ? 'That date has passed. Done measuring? Start the quote.' : (l.address ? esc(addr1(l.address, l.address2)) : 'No address on file yet.'),
        '<button type="button" class="m-btn primary" onclick="M.quoteForLead(\'' + js(l.id) + '\')">' + ic('file-plus') + 'Start quote</button>' +
        '<button type="button" class="m-btn ghost" onclick="M.surveyDate(\'' + js(l.id) + '\')">' + ic('calendar') + 'Reschedule</button>');
    } else if (l.status === 'send_quote' || l.status === 'quote_sent') {
      var drafts = quotes.filter(function (q) { return q.status === 'draft'; });
      next = nextCard('ruler', drafts.length ? 'Finish and send the quote' : 'Build the quote', drafts.length ? drafts[0].number + ' is a draft — send it when it is ready.' : 'Survey is done. Put the numbers together.',
        drafts.length ? '<button type="button" class="m-btn primary" onclick="M.go(\'quote\',\'' + js(drafts[0].id) + '\')">' + ic('send') + 'Open ' + esc(drafts[0].number) + '</button>' : '<button type="button" class="m-btn primary" onclick="M.quoteForLead(\'' + js(l.id) + '\')">' + ic('file-plus') + 'Build quote</button>');
    } else if (l.status === 'follow_up') {
      var fu = l.followUpDate;
      var late = fu && dayNum(fu) <= tnum;
      next = nextCard('clock', fu ? (late ? 'Follow up — due ' + whenDay(fu) : 'Follow up ' + whenDay(fu)) : 'Follow up', 'Check in on the quote and answer questions.',
        (l.phone ? '<a class="m-btn primary" href="' + esc(telHref(l.phone)) + '">' + ic('phone') + 'Call now</a>' : '') +
        '<button type="button" class="m-btn ghost" onclick="M.followUpDate(\'' + js(l.id) + '\')">' + ic('calendar') + (fu ? 'Change date' : 'Set date') + '</button>', late ? 'late' : '');
    }

    var info = '<div class="m-card m-kvs">' +
      kv('Phone', l.phone) + kv('Email', l.email) + kv('Address', addr1(l.address, l.address2)) +
      kv('Access details', l.sqFt) + kv('Project', l.projectType) + kv('Type', l.type) +
      kv('Source', l.source) + kv('Sales rep', repName(l.salesRepId) || 'Unassigned', { always: true }) +
      kv('Lead #', l.number) + kv('Created', l.createdAt ? whenDay(l.createdAt) + ' (' + ago(l.createdAt) + ')' : '') +
      '</div>';
    var contacts = (l.contacts || []).length ? section('Contacts', '<div class="m-card m-list-plain">' + l.contacts.map(contactRow).join('') + '</div>') : '';
    var qhtml = section('Quotes', quotes.length ? '<div class="m-list">' + quotes.map(function (q) { return quoteRow(q); }).join('') + '</div>' : '<p class="m-sub m-pad">No quotes yet.</p>', {
      count: quotes.length || null,
      more: '<button type="button" class="m-link" onclick="M.quoteForLead(\'' + js(l.id) + '\')">' + ic('plus') + 'New</button>'
    });
    var body =
      '<div class="m-hero">' + avatar(l.name, st.color) + '<div><h1>' + esc(l.name) + '</h1><p>' + stageChip(l.status) + '<span>' + esc([l.number, l.source].filter(Boolean).join(' · ')) + '</span></p></div></div>' +
      contactBar({ phone: l.phone, email: l.email, address: addr1(l.address, l.address2), entity: 'lead', id: l.id }) +
      ribbon + next + info + contacts + qhtml +
      notesSection('lead', l) +
      commsSection('lead', l) +
      '<div class="m-danger-zone">' +
      (l.status !== 'lost' && l.status !== 'approved' ? '<button type="button" class="m-btn ghost" onclick="M.leadLost(\'' + js(l.id) + '\')">' + ic('circle-x') + 'Mark lost</button>' : '') +
      '<button type="button" class="m-btn ghost danger" onclick="M.leadDelete(\'' + js(l.id) + '\')">' + ic('trash-2') + 'Delete lead</button></div>';
    return {
      title: l.name || 'Lead', back: true, big: false, body: body,
      actions: '<button type="button" class="m-icbtn" onclick="M.editLead(\'' + js(l.id) + '\')" aria-label="Edit lead">' + ic('pencil') + '</button>',
      after: function () { loadComms('lead', l); }
    };
  }

mobile:fn:nextCard.code:
function nextCard(icon, title, text, buttons, cls) {
    return '<div class="m-next' + (cls ? ' ' + cls : '') + '"><div class="m-next-hd">' + ic(icon) + '<div><small>Next step</small><b>' + esc(title) + '</b></div></div><p>' + text + '</p><div class="m-btnrow">' + buttons + '</div></div>';
  }

mobile:fn:kv.code:
function kv(label, value, opts) {
    opts = opts || {};
    if (!value && !opts.always) return '';
    return '<div class="m-kv"><span>' + esc(label) + '</span><b>' + (opts.html ? value : esc(value || '—')) + '</b></div>';
  }

mobile:fn:section.code:
function section(title, body, opts) {
    opts = opts || {};
    if (!body) return '';
    return '<section class="m-sec' + (opts.cls ? ' ' + opts.cls : '') + '">' + (title ? '<h2 class="m-sec-t">' + title + (opts.count != null ? '<span class="m-count">' + opts.count + '</span>' : '') + (opts.more || '') + '</h2>' : '') + body + '</section>';
  }

mobile:fn:quoteRow.code:
function quoteRow(q, extra, inCustomer) {
    var c = clientOf(q);
    var site = streetOf(q.siteAddress);
    if (inCustomer) c = { name: q.docName || site || q.number };
    var when = extra;
    if (!when) {
      if (q.status === 'sent') when = 'Sent ' + (ago(q.sentAt || q.createdAt) === 'today' ? 'today' : ago(q.sentAt || q.createdAt) + ' ago');
      else if (q.status === 'approved') when = 'Approved ' + (q.approvedAt ? whenDay(q.approvedAt) : '');
      else when = 'Created ' + whenDay(q.createdAt);
    }
    return '<button type="button" class="m-qrow" onclick="M.go(\'quote\',\'' + js(q.id) + '\')">' +
      '<span class="m-qrow-top"><b>' + esc(c.name) + '</b><strong>' + money(quoteTotal(q)) + '</strong></span>' +
      '<span class="m-qrow-bot"><small>' + esc((inCustomer ? [q.number, q.docName ? site : ''] : [q.number, q.docName || site]).filter(Boolean).join(' · ')) + '</small>' + quoteChip(q) + '</span>' +
      '<span class="m-qrow-when">' + esc(when) + '</span></button>';
  }

mobile:fn:quoteChip.code:
function quoteChip(q) {
    if (quoteExpired(q) && q.status === 'sent') return '<span class="m-chip c-red">Expired</span>';
    var s = QST[q.status] || [q.status || 'Draft', 'gray']; return '<span class="m-chip c-' + s[1] + '">' + esc(s[0]) + '</span>';
  }

mobile:fn:clientOf.code:
function clientOf(q) {
    var cu = q.customerId ? getCustomer(q.customerId) : null;
    if (cu) return { kind: 'customer', rec: cu, name: cu.name };
    var l = q.leadId ? getLead(q.leadId) : null;
    if (l) return { kind: 'lead', rec: l, name: l.name };
    return { kind: '', rec: null, name: q.siteContact || 'No customer' };
  }

mobile:fn:notesSection.code:
function notesSection(kind, r) {
    var notes = (Array.isArray(r.notes) ? r.notes : []).slice().reverse();
    var list = notes.length ? '<ul class="m-notes">' + notes.slice(0, 12).map(function (n) { return '<li><p>' + esc(n.text) + '</p><small>' + esc(n.date ? whenDay(n.date) : '') + '</small></li>'; }).join('') + '</ul>' : '';
    return section('Notes', '<div class="m-card"><div class="m-note-add"><textarea id="m-note-in" rows="1" placeholder="Add a note…" oninput="this.style.height=\'auto\';this.style.height=this.scrollHeight+\'px\'"></textarea><button type="button" class="m-btn primary sm" onclick="M.addNote(\'' + kind + '\',\'' + js(r.id) + '\')">Add</button></div>' + list + '</div>', { count: notes.length || null });
  }

mobile:fn:segs.code:
function segs(name, current, items) {
    return '<div class="m-segs" role="tablist">' + items.map(function (it) {
      var on = it.k === current;
      return '<button type="button" role="tab" aria-selected="' + on + '" class="m-seg' + (on ? ' on' : '') + '" onclick="M.setFilter(\'' + name + '\',\'' + it.k + '\')">' + esc(it.label) + (it.n != null ? '<i>' + it.n + '</i>' : '') + '</button>';
    }).join('') + '</div>';
  }

mobile:text:STAGE.code:
var STAGE = {
    new: { label: 'New', short: 'New', color: 'blue' },
    site_survey_scheduled: { label: 'Site survey', short: 'Survey', color: 'indigo' },
    send_quote: { label: 'Send quote', short: 'Quote', color: 'amber' },
    quote_sent: { label: 'Send quote', short: 'Quote', color: 'amber' },
    follow_up: { label: 'Follow-up', short: 'Follow-up', color: 'pink' },
    approved: { label: 'Approved', short: 'Won', color: 'green' },
    lost: { label: 'Lost', short: 'Lost', color: 'gray' }
  };

mobile:text:M.leadStage.code:
M.leadStage = function (id, s) {
    var l = getLead(id); if (!l) return;
    if (s === 'site_survey_scheduled') { M.surveyDate(id); return; }
    if (l.status === s) return;
    // Moving back to New clears a planned survey the same way the desktop does.
    if (s === 'new' && l.siteSurveyDate && l.status === 'site_survey_scheduled') { setLeadSurveyDate(id, ''); toast('Moved back to New'); return; }
    changeLeadStatus(id, s);
    toast(l.name + ' → ' + stage(s).label);
  };

mobile:text:M.surveyDate.code:
M.surveyDate = function (id) {
    var l = getLead(id); if (!l) return;
    var cur = l.siteSurveyDate ? String(l.siteSurveyDate).slice(0, 10) : '';
    var t = new Date(), quick = [0, 1, 2, 3, 4, 5, 6].map(function (i) { var d = new Date(t.getFullYear(), t.getMonth(), t.getDate() + i); return localISO(d); });
    var body = sheet('<p class="m-sub">Pick the day you will measure at ' + esc(streetOf(l.address) || 'the site') + '.</p>' +
      '<div class="m-days">' + quick.map(function (d) { var dt = new Date(d + 'T12:00:00'); return '<button type="button" class="m-day' + (d === cur ? ' on' : '') + '" data-d="' + d + '"><small>' + (d === quick[0] ? 'Today' : dt.toLocaleDateString('en-US', { weekday: 'short' })) + '</small><b>' + dt.getDate() + '</b></button>'; }).join('') + '</div>' +
      '<label class="m-field"><span>Or choose a date</span><input type="date" id="m-survey-d" value="' + esc(cur) + '"></label>' +
      '<div class="m-btnrow">' + (cur ? '<button type="button" class="m-btn ghost danger" data-clear>Clear date</button>' : '') + '<button type="button" class="m-btn primary" data-save>Save</button></div>', { title: 'Site survey' });
    // setLeadSurveyDate posts its own confirmation.
    var pick = function (d) { if (!d) return; closeTopSheet(); setLeadSurveyDate(id, d); };
    body.querySelectorAll('.m-day').forEach(function (b) { b.onclick = function () { pick(b.dataset.d); }; });
    body.querySelector('[data-save]').onclick = function () { pick(body.querySelector('#m-survey-d').value); };
    var c = body.querySelector('[data-clear]'); if (c) c.onclick = function () { closeTopSheet(); setLeadSurveyDate(id, ''); toast('Survey date cleared'); };
  };

mobile:text:M.followUpDate.code:
M.followUpDate = function (id) {
    var l = getLead(id); if (!l) return;
    var cur = l.followUpDate ? String(l.followUpDate).slice(0, 10) : '';
    var opts = [[1, 'Tomorrow'], [3, 'In 3 days'], [7, 'Next week'], [14, 'In 2 weeks']];
    var body = sheet('<div class="m-chips">' + opts.map(function (o) { var d = new Date(); d.setDate(d.getDate() + o[0]); return '<button type="button" class="m-chipbtn" data-d="' + localISO(d) + '">' + o[1] + '</button>'; }).join('') + '</div>' +
      '<label class="m-field"><span>Date</span><input type="date" id="m-fu-d" value="' + esc(cur) + '"></label>' +
      '<div class="m-btnrow"><button type="button" class="m-btn primary" data-save>Save</button></div>', { title: 'Follow-up date' });
    var set = function (d) { closeTopSheet(); updateLeadFollowUp(id, d || null); render(); toast(d ? 'Follow up ' + whenDay(d) : 'Follow-up date cleared'); };
    body.querySelectorAll('[data-d]').forEach(function (b) { b.onclick = function () { set(b.dataset.d); }; });
    body.querySelector('[data-save]').onclick = function () { set(body.querySelector('#m-fu-d').value); };
  };

mobile:text:M.leadLost.code:
M.leadLost = function (id) {
    var l = getLead(id); if (!l) return;
    confirmSheet('Mark as lost?', esc(l.name) + ' moves to Lost. You can reopen it later.', 'Mark lost', function () { changeLeadStatus(id, 'lost'); toast(l.name + ' marked lost'); }, { danger: true });
  };

mobile:text:M.newLead.code:
M.newLead = function (prefill) {
    if (!can('leads')) return;
    prefill = prefill || {};
    var types = []; try { types = getCustomerTypes(); } catch (_) { types = ['Retail']; }
    var body = sheet('<form class="m-form" novalidate>' +
      '<label class="m-field"><span>Name *</span><input name="name" autocomplete="name" autocapitalize="words" required value="' + esc(prefill.name || '') + '" autofocus></label>' +
      '<label class="m-field"><span>Phone *</span><input name="phone" type="tel" inputmode="tel" autocomplete="tel" required value="' + esc(prefill.phone || '') + '"></label>' +
      '<label class="m-field"><span>Email</span><input name="email" type="email" inputmode="email" autocomplete="email" autocapitalize="off"></label>' +
      addrField('m-nl-addr', 'Address', '', '') +
      chipsField('projectType', 'Project', PROJECT_TYPES, '') +
      chipsField('source', 'How they found us', SOURCES, prefill.source || '') +
      '<div class="m-2col"><label class="m-field"><span>Customer type</span><select name="type">' + types.map(function (t) { return opt(t, t, t === 'Retail'); }).join('') + '</select></label>' +
      '<label class="m-field"><span>Sales rep</span><select name="salesRepId">' + repOptions(myRepId()) + '</select></label></div>' +
      '<label class="m-field"><span>Site survey date</span><input name="siteSurveyDate" type="date"></label>' +
      '<label class="m-field"><span>Access details</span><input name="sqFt" placeholder="Gate code, parking, pets…"></label>' +
      '<label class="m-field"><span>Note</span><textarea name="noteText" rows="2" placeholder="What do they need?"></textarea></label>' +
      '<button type="submit" class="m-btn primary block">' + ic('check') + 'Save lead</button></form>', { title: 'New lead', full: true });
    wireChips(body);
    try { setupAddressAutocomplete('m-nl-addr'); } catch (_) { }
    var form = body.querySelector('form');
    form.onsubmit = function (e) {
      e.preventDefault();
      if (need(form, 'name', 'Name is required') || need(form, 'phone', 'Phone is required')) return;
      var v = formVals(form);
      dupCheck('lead', { name: v.name, phone: v.phone, email: v.email, address: v.address }, null, function () {
        var l = _createLeadRecord(v);
        closeAllSheets();
        toast('Lead ' + l.number + ' added');
        M.go('lead', l.id);
      });
    };
  };

