index:text:jc-metric-bar.code:
${_jcMetricBar([
  {label:'Revenue',value:fmt$(fin.revenue),tone:'blue',note:fin.revSource==='invoice'?'invoiced':'quoted',title:fin.revSource==='invoice'?'From the invoices on this job, tax excluded':"The work order's quoted retail — nothing invoiced yet"},
  {label:'Estimated',value:fmt$(est),note:'quoted cost',title:'Quoted materials + labor'+(fin.isGroup?` across ${fin.members.length} work orders`:'')},
  {label:'Actual',value:fmt$(act),note:recTot.n+' recorded',title:recTot.n+' recorded cost'+(recTot.n===1?'':'s')+(recTot.bills?` · ${recTot.bills} entered in Accounting`:'')},
  {label:'Variance',value:(act-est>0.005?'+':(act-est<-0.005?'−':''))+fmt$(Math.abs(act-est)),tone:act-est>0.005?'red':'green',note:act-est>0.005?'over':'under',title:'Actual cost against the quote'},
  {label:'Margin',value:'<span class="qb-private">'+fin.margin.toFixed(1)+'%</span>',tone:fin.margin>=0?'blue':'red',note:'before commission',title:'Revenue less cost, before the sales commission — how well the job itself ran'},
  {label:'Profit',value:'<span class="qb-private">'+fmt$(fin.profit)+'</span>',tone:fin.profit>=0?'green':'red',note:'after commission',title:'Revenue less cost and commission — the bottom line on this job'},
  {label:'Sales Tax',value:fmt$(fin.tax),tone:'amber',note:fin.taxSource==='invoice'?'invoiced':'quoted',title:fin.taxSource==='invoice'?'Invoiced and held for the state — never revenue':"Quoted on the work order — held for the state, never revenue"}
])}
